            else => null,
        },
        .@"opt_items" => switch (slot) {
            1 => .@"item",
            2 => .@"sep",
            else => null,
        },
        .@"group" => switch (slot) {
            1 => .@"kind",
            else => null,
        },
        .@"quantified" => switch (slot) {
            1 => .@"element",
            2 => .@"quant",
            else => null,
        },
        .@"skip_q" => switch (slot) {
            1 => .@"element",
            2 => .@"quant",
            else => null,
        },
        .@"skip" => switch (slot) {
            1 => .@"element",
            else => null,
        },
        .@"exclude" => switch (slot) {
            1 => .@"char",
            else => null,
        },
        .@"label" => switch (slot) {
            1 => .@"name",
            2 => .@"element",
            else => null,
        },
        .@"pos" => switch (slot) {
            1 => .@"n",
            else => null,
        },
        .@"spread" => switch (slot) {
            1 => .@"n",
            else => null,
        },
        .@"symid" => switch (slot) {
            1 => .@"n",
            else => null,
        },
        .@"tag" => switch (slot) {
            1 => .@"word",
            else => null,
        },
        .@"named" => switch (slot) {
            1 => .@"role",
            2 => .@"value",
            else => null,
        },
        .@"node" => switch (slot) {
            1 => .@"head",
            else => null,
        },
        .@"keep" => switch (slot) {
            1 => .@"n",
            else => null,
        },
        else => null,
    };
}

fn restRoleOf(kind: Tag) ?struct { role: Role, slot: usize } {
    return switch (kind) {
        .@"grammar" => .{ .role = .@"entries", .slot = 1 },
        .@"manifest" => .{ .role = .@"entries", .slot = 1 },
        .@"as" => .{ .role = .@"groups", .slot = 3 },
        .@"op" => .{ .role = .@"maps", .slot = 1 },
        .@"errors" => .{ .role = .@"pairs", .slot = 1 },
        .@"display" => .{ .role = .@"pairs", .slot = 1 },
        .@"infix" => .{ .role = .@"levels", .slot = 2 },
        .@"level" => .{ .role = .@"ops", .slot = 1 },
        .@"schema" => .{ .role = .@"decls", .slot = 1 },
        .@"kinds" => .{ .role = .@"names", .slot = 1 },
        .@"sides" => .{ .role = .@"names", .slot = 1 },
        .@"roles" => .{ .role = .@"roles", .slot = 1 },
        .@"type" => .{ .role = .@"atoms", .slot = 1 },
        .@"tagset" => .{ .role = .@"values", .slot = 2 },
        .@"tags" => .{ .role = .@"names", .slot = 1 },
        .@"trivia" => .{ .role = .@"names", .slot = 1 },
        .@"repair" => .{ .role = .@"lines", .slot = 1 },
        .@"repair_line" => .{ .role = .@"names", .slot = 2 },
        .@"rule" => .{ .role = .@"alts", .slot = 2 },
        .@"group" => .{ .role = .@"bodies", .slot = 2 },
        .@"node" => .{ .role = .@"items", .slot = 2 },
        .@"list" => .{ .role = .@"items", .slot = 1 },
        .@"keep" => .{ .role = .@"items", .slot = 2 },
        else => null,
    };
}

// =============================================================================
// API
// =============================================================================

pub const Parser = if (@hasDecl(lang, "Parser")) lang.Parser else BaseParser;

/// Parse a whole grammar with a new `Parser`. The caller owns
/// `result.parser` and must `deinit()` it when done with the tree.
pub fn parseGrammar(allocator: std.mem.Allocator, source: []const u8) !struct { parser: Parser, sexp: Sexp } {
    var p = Parser.init(allocator, source);
    errdefer p.deinit();
    const sexp = try p.parseGrammar();
    return .{ .parser = p, .sexp = sexp };
}
